  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C01","C02","C03","C04","C05","C07","C08","C09","C10","C11",
    "C13","C14","C16","C17","C18","C19","C20","C21","C22","C23",
    "C24","C25","C26","C59","C60","C62","C63","C64","C67","C68","C69"
  ],
  "contradictory_card_ids": ["C58"],
  "prediction_basis_card_ids": [
    "C01","C02","C13","C14","C18","C19","C20","C22",
    "C59","C60","C62","C63","C64","C67","C68","C69"
  ],
  "claims": [
    {
      "claim": "The query is a diltiazem-type benzothiazepine with a basic tertiary amine, moderate logD (2.09), no HBD, and TPSA 59; no supplied record directly measures its absolute oral bioavailability, but all numeric L1 gold records for the visible contexts report F values above 20% (apixaban 49-50%, tamoxifen ~100%, encainide 76-78%, midodrine 90-100%, pentopril 50-70%, cefroxadine ~100%).",
      "card_ids": ["C01","C02","C03","C04","C05","C07","C08","C09","C10","C11","C13","C14","C16","C17","C18","C19","C20","C21","C22","C23","C24","C25","C26"]
    },
    {
      "claim": "Apixaban, which shares methoxyphenyl and lactam features with the query, remains above the threshold even under strong CYP3A4/P-gp induction (37-39% with rifampin), and its species values (30% rat, 70-88% dog) are all above 20%.",
      "card_ids": ["C01","C02","C13","C14","C18","C19","C20","C22","C27","C35","C36","C39","C42","C44"]
    },
    {
      "claim": "The only sub-20% values in the visible records are species- or metabolite-specific tamoxifen records (horse F 13.15%; 4-OHT poor due to glucuronidation) and do not transfer to the query's human oral context.",
      "card_ids": ["C28","C31"]
    },
    {
      "claim": "L4 intestinal absorption/permeability records for basic amine drugs (imipramine 100% human absorption; diphenhydramine, chlorpromazine, promethazine high Caco-2 permeability) support efficient intestinal absorption for the query's basic amine, moderate logD profile.",
      "card_ids": ["C59","C60","C62","C63","C64","C67","C68","C69"]
    },
    {
      "claim": "The apixaban Caco-2 efflux record (C58) is not threshold-relevant: apixaban has F=50% in humans despite B→A > A→B, so efflux alone does not establish F<20% for the query.",
      "card_ids": ["C58","C01","C14","C18"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C59","C60","C62","C63","C64","C67","C68","C69"]
    },
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C58","C61","C65","C66"]
    }
  ],
  "evidence_gaps": [
    "No direct diltiazem-specific absolute F measurement is present in any supplied record.",
    "No IV comparator or F denominator accompanies the L3 AUC/Cmax values, so they cannot establish absolute bioavailability.",
    "First-pass metabolism and ester hydrolysis of the query are not directly quantified in the supplied records.",
    "No human F value for the exact benzothiazepine scaffold is available; transfer remains analog-based.",
    "L4 permeability/absorption records are indirect and do not quantify systemic first-pass loss."
  ],
  "decision_summary": "L4 intestinal absorption/permeability evidence is moderately applicable and supportive: high human absorption and high Caco-2 permeability records for basic amine drugs align with the query's physicochemical profile, while the apixaban efflux record is not threshold-relevant because apixaban still has F=50%. No affirmative threshold-relevant low-F evidence for the query appears. The prior high prediction is retained and modestly strengthened, with moderate confidence; no flip or weakening."
}

